import { BuildCtx } from "./ctx"
import { ProcessedContent } from "../plugins/vfile"
import { FullSlug, SimpleSlug, simplifySlug } from "./path"
import { filteredBy, recordDiagnostic } from "./diagnostics"

export interface UnresolvedLink {
  from: FullSlug
  to: SimpleSlug
  /** Why the target is missing, when Quartz knows (e.g. "removed by filter Drafts"). */
  reason?: string
}

/**
 * Internal links whose target is not part of the built site — checked after emitting, so pages
 * generated by page types (tags, folders, bases) count as existing. Links to pages removed by a
 * filter (drafts, unpublished, …) are reported with that filter as the reason, which explains the
 * most common "this link 404s" question.
 */
export function findUnresolvedLinks(ctx: BuildCtx, content: ProcessedContent[]): UnresolvedLink[] {
  const existing = new Set<string>()
  // allSlugs lists every source file — including pages a filter removed (drafts …), which are
  // exactly the links that 404, so leave those out.
  for (const slug of ctx.allSlugs) {
    if (!filteredBy(slug)) existing.add(simplifySlug(slug))
  }
  for (const [, file] of content) {
    if (file.data.slug) existing.add(simplifySlug(file.data.slug as FullSlug))
  }
  for (const slug of ctx.contentIndex?.keys() ?? []) existing.add(simplifySlug(slug))

  const unresolved: UnresolvedLink[] = []
  for (const [, file] of content) {
    const from = file.data.slug as FullSlug | undefined
    if (!from) continue
    // normalise: some plugins write full slugs ("folder/index") instead of simple ones ("folder/")
    for (const to of new Set(
      (file.data.links ?? []).map((l) => simplifySlug(l as unknown as FullSlug)),
    )) {
      if (existing.has(to)) continue
      // the site root, and folder links whose folder page has an index
      if (to === "/" || existing.has(`${to}index` as SimpleSlug)) continue
      const removedBy = filteredBy(to.endsWith("/") ? `${to}index` : to)
      unresolved.push({
        from,
        to,
        reason: removedBy ? `removed by filter ${removedBy}` : undefined,
      })
    }
  }
  return unresolved
}

/** Record a one-line note about unresolved links; `--verbose` prints every link. */
export function reportUnresolvedLinks(
  ctx: BuildCtx,
  content: ProcessedContent[],
): UnresolvedLink[] {
  const unresolved = findUnresolvedLinks(ctx, content)
  if (unresolved.length === 0) return unresolved

  const pages = new Set(unresolved.map((u) => u.from)).size
  const filtered = unresolved.filter((u) => u.reason)
  const examples = (filtered.length > 0 ? filtered : unresolved)
    .slice(0, 3)
    .map((u) => `${u.from} → ${u.to}${u.reason ? ` (${u.reason})` : ""}`)
    .join(", ")
  recordDiagnostic({
    severity: "info",
    area: "links",
    message:
      `${unresolved.length} link${unresolved.length === 1 ? "" : "s"} in ${pages} page${pages === 1 ? "" : "s"} ` +
      `${unresolved.length === 1 ? "points" : "point"} to pages that are not on the site${filtered.length > 0 ? ` (${filtered.length} to pages removed by a filter, e.g. drafts)` : ""}: ${examples}`,
    hint: ctx.argv.verbose
      ? undefined
      : "Run with --verbose to list them all. Links to notes you haven't written yet are expected.",
  })
  if (ctx.argv.verbose) {
    for (const u of unresolved) {
      recordDiagnostic({
        severity: "info",
        area: "links",
        message: `${u.from} → ${u.to}${u.reason ? ` (${u.reason})` : " (no such page)"}`,
      })
    }
  }
  return unresolved
}
